import React, { useEffect, useRef, useState } from "react";
import pic from "../Assets/new.png";
import { useNavigate } from "react-router-dom";
import axios from "axios";

const Discount = () => {
  const [visible, setVisible] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    course: "Full Stack Development",
    phone: "",
  });
  const [selectedPlan, setSelectedPlan] = useState(null);
  const sectionRef = useRef();
  const navigate = useNavigate();

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  const handleModalSubmit = async (e) => {
    e.preventDefault();
    setIsModalOpen(false);

    if (selectedPlan) {
      const amount =
        selectedPlan === "Basic"
          ? 19
          : selectedPlan === "Standard"
          ? 49
          : 99;

      try {
        // ✅ Save EnrollForm and get enrollId
        const enrollRes = await axios.post("http://localhost:5000/api/enroll-form", {
          name: formData.name,
          email: formData.email,
          phone: formData.phone || "",
          course: formData.course,
          plan: selectedPlan,
          amount: amount,
        });

        const enrollId = enrollRes.data.enroll._id;

        // Navigate to Payment page with enrollId
        navigate(
          `/payment?name=${encodeURIComponent(formData.name)}&email=${encodeURIComponent(
            formData.email
          )}&course=${encodeURIComponent(selectedPlan)}&amount=${amount}&enrollId=${enrollId}`
        );
      } catch (err) {
        console.error("Error saving enrollment:", err);
      }
    }
  };

  const handlePlanClick = async (plan) => {
    if (!formData.name || !formData.email) {
      setSelectedPlan(plan);
      setIsModalOpen(true);
      return;
    }

    const amount = plan === "Basic" ? 19 : plan === "Standard" ? 49 : 99;

    try {
      const enrollRes = await axios.post("http://localhost:5000/api/enroll-form", {
        name: formData.name,
        email: formData.email,
        phone: formData.phone || "",
        course: formData.course,
        plan: plan,
        amount: amount,
      });

      const enrollId = enrollRes.data.enroll._id;

      navigate(
        `/payment?name=${encodeURIComponent(formData.name)}&email=${encodeURIComponent(
          formData.email
        )}&course=${encodeURIComponent(plan)}&amount=${amount}&enrollId=${enrollId}`
      );
    } catch (err) {
      console.error("Error saving enrollment:", err);
    }
  };

  return (
    <div ref={sectionRef} className="overflow-x-hidden overflow-y-hidden" id="price">
      <div className="h-auto w-100 bg-purple-100">
        <div
          className={`flex flex-col w-[70%] border rounded-3xl gap-6 mx-auto pb-10 justify-center mt-5 items-center transition-all duration-1000 ${
            visible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
          }`}
        >
          <div className="border border-purple-400 rounded-full px-4 py-4 mt-16">
            <img src={pic} alt="" className="h-20" />
          </div>
          <div className="text-4xl text-center font-bold">
            <h1>
              Happy New Year, 20% Discount <br /> For You Today
            </h1>
          </div>
          <div className="text-center pb-8">
            <p>
              Excepteur sint occaecat cupidatat non proident, sunt in <br /> culpa
              qui officia deserunt mollit anim id est laborum.
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full px-6">
            {[
              {
                plan: "Basic",
                price: "$19",
                features: ["Access to 10 courses", "Email support", "Community access"],
              },
              {
                plan: "Standard",
                price: "$49",
                features: ["Everything in Basic", "50+ Courses", "Certificates included"],
              },
              {
                plan: "Premium",
                price: "$99",
                features: ["All Courses", "1-on-1 Mentorship", "Exclusive Resources"],
              },
            ].map((item, index) => (
              <div
                key={index}
                className="bg-white border rounded-2xl p-6 shadow-md flex flex-col items-center"
              >
                <h2 className="text-2xl font-bold text-purple-600">{item.plan}</h2>
                <p className="text-3xl font-bold my-4">{item.price}/mo</p>
                <ul className="text-gray-700 space-y-2 text-center mb-6">
                  {item.features.map((feature, i) => (
                    <li key={i}>✅ {feature}</li>
                  ))}
                </ul>
                <button
                  onClick={() => handlePlanClick(item.plan)}
                  className="px-6 py-3 bg-purple-500 text-white rounded-xl hover:bg-purple-600 transition"
                >
                  Get Started
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
          <div className="bg-white rounded-2xl shadow-lg p-8 w-[90%] max-w-md relative">
            <button
              onClick={() => setIsModalOpen(false)}
              className="absolute top-3 right-3 text-gray-500 hover:text-black"
            >
              ✖
            </button>
            <h2 className="text-2xl font-bold text-purple-600 mb-4">Enter your details</h2>
            <form className="space-y-4" onSubmit={handleModalSubmit}>
              <div>
                <label className="block text-sm font-medium text-gray-700">Name</label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  className="w-full p-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-400"
                  placeholder="Enter your name"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700">Email</label>
                <input
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  className="w-full p-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-400"
                  placeholder="Enter your email"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700">Course Preference</label>
                <select
                  value={formData.course}
                  onChange={(e) => setFormData({ ...formData, course: e.target.value })}
                  className="w-full p-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-400"
                >
                  <option>Full Stack Development</option>
                  <option>Data Science</option>
                  <option>Artificial Intelligence</option>
                  <option>Digital Marketing</option>
                </select>
              </div>
              <button
                type="submit"
                className="w-full bg-purple-500 text-white py-2 rounded-lg hover:bg-purple-600 transition"
              >
                Continue to Payment
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Discount;
