// src/pages/MyDiscounts.jsx
import React, { useEffect, useState } from "react";

const MyDiscounts = ({ email }) => {
  const [discounts, setDiscounts] = useState([]);

  useEffect(() => {
    if (!email) return; // jab tak email na mile, request mat bhejo
    fetch(`http://localhost:5000/api/my-discounts/${email}`)
      .then((res) => res.json())
      .then((data) => setDiscounts(data.leads || [])) // backend se 'leads' aa raha hai
      .catch((err) => console.error(err));
  }, [email]);

  return (
    <div className="p-10 bg-gray-100 min-h-screen">
      <h1 className="text-2xl font-bold text-purple-700 mb-6">My Discounts</h1>
      {discounts.length === 0 ? (
        <p>No discounts enrolled yet.</p>
      ) : (
        <ul className="space-y-4">
          {discounts.map((d, i) => (
            <li key={i} className="bg-white shadow-md rounded-lg p-4">
              <h2 className="font-bold">{d.course}</h2>
              <p>Email: {d.email}</p>
              <p>Name: {d.name}</p>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default MyDiscounts;
