

import React, { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";

const Success = () => {
  const [searchParams] = useSearchParams();
  const [status, setStatus] = useState("Saving payment info...");
  const sessionId = searchParams.get("session_id");

  useEffect(() => {
    const savePayment = async () => {
      try {
        const res = await fetch("http://localhost:5000/api/save-payment", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ sessionId }),
        });

        const data = await res.json();
        if (res.ok && data.success) {
          setStatus("✅ Payment successful! Your enrollment has been saved.");
        } else {
          setStatus("⚠️ Payment succeeded but failed to save in database.");
        }
      } catch (err) {
        console.error("Error saving payment:", err);
        setStatus("❌ Error saving payment info. Please contact support.");
      }
    };

    if (sessionId) {
      savePayment();
    } else {
      setStatus("❌ Missing payment session ID.");
    }
  }, [sessionId]);

  return (
    <div className="flex items-center justify-center h-screen bg-purple-50">
      <div className="bg-white rounded-2xl shadow-lg p-10 text-center max-w-lg">
        <div className="text-5xl mb-4">🎉</div>
        <h1 className="text-3xl font-bold text-purple-600 mb-2">Thank You!</h1>
        <p className="text-gray-600 mb-4">{status}</p>
        <a
          href="/"
          className="inline-block px-6 py-3 bg-purple-500 text-white rounded-lg hover:bg-purple-600 transition"
        >
          Go back to Home
        </a>
      </div>
    </div>
  );
};

export default Success;
