// export default EnrollForm;


import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

const EnrollForm = () => {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    course: "",
  });

  const [status, setStatus] = useState("");

  // Auto-fill email from logged-in user
  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("user"));
    if (user && user.email) {
      setFormData((prev) => ({ ...prev, email: user.email }));
    }
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus("Submitting...");
    try {
      const res = await fetch("http://localhost:5000/api/enroll-form", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      let data = await res.json();

      if (res.ok) {
        setStatus("Enrollment successful!");
        setFormData({ name: "", email: formData.email, phone: "", course: "" });

        // redirect to dashboard so enrolled course is visible
        setTimeout(() => {
          navigate("/dashboard");
        }, 1000);
      } else {
        setStatus(data.message || `Error ${res.status}`);
      }
    } catch (err) {
      console.error("Fetch/network error:", err);
      setStatus("Network/server error — check console and server logs.");
    }
  };

  return (
    <div className="max-w-md mx-auto bg-gradient-to-t from-purple-100 to-purple-200 shadow-xl rounded-2xl p-6 mt-8">
      <h2 className="text-2xl font-bold text-center mb-4">Enroll Now</h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        <input
          type="text"
          name="name"
          placeholder="Full Name"
          value={formData.name}
          onChange={handleChange}
          className="w-full border rounded-lg p-2 focus:outline-none focus:ring-2 focus:ring-purple-100"
          required
        />
        <input
          type="email"
          name="email"
          placeholder="Email Address"
          value={formData.email}
          onChange={handleChange}
          disabled // lock user email
          className="w-full border rounded-lg p-2 bg-gray-100 text-gray-600"
        />
        <input
          type="text"
          name="phone"
          placeholder="Phone Number"
          value={formData.phone}
          onChange={handleChange}
          className="w-full border rounded-lg p-2 focus:outline-none focus:ring-2 focus:ring-purple-100"
          required
        />
        <input
          type="text"
          name="course"
          placeholder="Course Name"
          value={formData.course}
          onChange={handleChange}
          className="w-full border rounded-lg p-2 focus:outline-none focus:ring-2 focus:ring-purple-100"
          required
        />
        <button
          type="submit"
          className="w-full bg-purple-500 hover:bg-purple-600 text-white font-semibold py-2 rounded-lg"
        >
          Submit
        </button>
      </form>
      {status && <p className="text-center mt-3 text-sm">{status}</p>}
    </div>
  );
};

export default EnrollForm;
