import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { FaCreditCard, FaMoneyBillWave, FaMobileAlt } from 'react-icons/fa';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const PaymentPage = () => {
  const location = useLocation();
  const navigate = useNavigate(); // ✅ navigation
  const query = new URLSearchParams(location.search);

  const nameQuery = query.get('name');
  const emailQuery = query.get('email');
  const course = query.get('course');
  const amount = parseFloat(query.get('amount')) || 0;
  const enrollId = query.get('enrollId');

  const [loading, setLoading] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('card');
  const [cardNumber, setCardNumber] = useState('');
  const [cashName, setCashName] = useState(nameQuery || '');
  const [cashPhone, setCashPhone] = useState('');
  const [jazzPhone, setJazzPhone] = useState('');

  const handlePayment = async () => {
    // Validation
    if (paymentMethod === "card" && !cardNumber) return toast.error("Please enter card number");
    if (paymentMethod === "cash" && (!cashName || !cashPhone)) return toast.error("Please enter name and phone");
    if (paymentMethod === "jazzcash" && !jazzPhone) return toast.error("Please enter JazzCash number");

    setLoading(true);
    try {
      const payload = {
        name: paymentMethod === "cash" ? cashName : nameQuery,
        email: emailQuery,
        course,
        amount,
        paymentMethod,
        currency: "usd",
        status: "success", // ✅ save as success
        cardNumber: paymentMethod === "card" ? cardNumber : undefined,
        cashName: paymentMethod === "cash" ? cashName : undefined,
        cashPhone: paymentMethod === "cash" ? cashPhone : undefined,
        jazzPhone: paymentMethod === "jazzcash" ? jazzPhone : undefined,
        enrollId,
      };

      const res = await fetch("http://localhost:5000/api/save-payment-method", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await res.json();
      if (!res.ok) {
        toast.error(`Error: ${data.message || "Unknown error"}`);
      } else {
        toast.success(`${paymentMethod} payment saved successfully!`);
        // ✅ redirect after 2 seconds to home
        setTimeout(() => {
          navigate('/');
        }, 2000);
      }
    } catch (err) {
      console.error(err);
      toast.error("Payment error occurred.");
    } finally {
      setLoading(false);
    }
  };

  const methodIcons = {
    card: <FaCreditCard size={30} className="mx-auto mb-2 text-purple-600" />,
    cash: <FaMoneyBillWave size={30} className="mx-auto mb-2 text-green-600" />,
    jazzcash: <FaMobileAlt size={30} className="mx-auto mb-2 text-blue-600" />,
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-purple-100 to-white flex items-center justify-center p-6">
      <ToastContainer position="top-right" autoClose={3000} />
      <div className="w-full max-w-2xl bg-white rounded-3xl shadow-2xl p-8 space-y-6">
        <h1 className="text-4xl font-extrabold text-purple-700 text-center">Complete Your Payment</h1>
        <div className="flex justify-between text-gray-700 text-lg">
          <p>Course: <span className="font-semibold">{course}</span></p>
          <p>Amount: <span className="font-bold text-purple-600">${amount}</span></p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {['card', 'cash', 'jazzcash'].map((method) => (
            <div
              key={method}
              onClick={() => setPaymentMethod(method)}
              className={`cursor-pointer border-2 rounded-2xl p-6 text-center transition transform hover:-translate-y-1 hover:shadow-lg ${
                paymentMethod === method
                  ? 'border-purple-600 bg-purple-50 shadow-xl scale-105'
                  : 'border-gray-300'
              }`}
            >
              {methodIcons[method]}
              <p className="font-bold capitalize">{method}</p>
            </div>
          ))}
        </div>

        <div className="space-y-4">
          {paymentMethod === 'card' && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Card Number</label>
              <input
                type="text"
                value={cardNumber}
                onChange={(e) => setCardNumber(e.target.value)}
                placeholder="1234 5678 9012 3456"
                className="w-full p-4 border rounded-2xl focus:ring-2 focus:ring-purple-400 outline-none text-lg"
              />
            </div>
          )}

          {paymentMethod === 'cash' && (
            <div className="space-y-3">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                <input
                  type="text"
                  value={cashName}
                  onChange={(e) => setCashName(e.target.value)}
                  placeholder="Enter your name"
                  className="w-full p-4 border rounded-2xl focus:ring-2 focus:ring-green-400 outline-none text-lg"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Phone Number</label>
                <input
                  type="text"
                  value={cashPhone}
                  onChange={(e) => setCashPhone(e.target.value)}
                  placeholder="Enter your phone"
                  className="w-full p-4 border rounded-2xl focus:ring-2 focus:ring-green-400 outline-none text-lg"
                />
              </div>
            </div>
          )}

          {paymentMethod === 'jazzcash' && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">JazzCash Number</label>
              <input
                type="text"
                value={jazzPhone}
                onChange={(e) => setJazzPhone(e.target.value)}
                placeholder="Enter your JazzCash number"
                className="w-full p-4 border rounded-2xl focus:ring-2 focus:ring-blue-400 outline-none text-lg"
              />
            </div>
          )}
        </div>

        <button
          onClick={handlePayment}
          disabled={loading}
          className="w-full bg-gradient-to-r from-purple-600 to-purple-800 text-white py-4 rounded-2xl hover:from-purple-700 hover:to-purple-900 transition font-bold text-lg shadow-lg"
        >
          {loading ? 'Processing...' : 'Proceed to Payment'}
        </button>
      </div>
    </div>
  );
};

export default PaymentPage;
