

// src/Components/HeroSection.js
import React from 'react';
import { Link } from 'react-router-dom';
import bg from "../Assets/bg.png";   // same bg image you used in Bar.js

const HeroSection = () => {
  return (
    <div
      style={{ backgroundImage: `url(${bg})` }}
      className='w-full bg-no-repeat bg-cover pt-10 pb-4 '
    >
      <div
        className='text-center items-center font-bold  px-20 py-10'
        id='tt'
      >
        <h1 className='lg:pt-10 text-6xl'>
          There's Always More to <br /> Discover and Learn
        </h1>
        <div className="text-center mt-6 font-normal">
          <p>
            Ideal for creatives. Learn design, photography, writing, and more from industry pros.
          </p>
        </div>
        <div className="button flex justify-center mt-4">
          <Link to='/EnrollForm'>
            <button
              className='border  lg:mt-6 px-6 py-4 bg-purple-500 rounded-2xl text-white hover:bg-purple-600 text-base'
            >
              ENROLL NOW
            </button>
          </Link>
        </div>
      </div>
    </div>
  );
};

export default HeroSection;
