import React from "react";
import { Link } from "react-router-dom";
import web from "../Assets/fs3.png";
import pm from "../Assets/pm1.avif";
import dm from "../Assets/dm1.webp";
import ds from "../Assets/ds.jpg"; // Data Science image (add in Assets)
import ai from "../Assets/ai.jpeg"; // Artificial Intelligence image (add in Assets)

const courses = [
  {
    title: "Full Stack Web Development",
    description: "Learn to build modern web apps with React, Node & MongoDB.",
    rating: 4.7,
    students: "4.7K",
    link: "/fullstack-roadmap",
    image: web,
  },
  {
    title: "Digital Marketing",
    description:
      "Master SEO, social media & campaigns to grow any business online.",
    rating: 4.7,
    students: "4.7K",
    link: "/digital-marketing-roadmap",
    image: dm,
  },
  {
    title: "Project Management",
    description:
      "Plan, execute & deliver projects with real-world PM skills.",
    rating: 4.7,
    students: "4.7K",
    link: "/project-management-roadmap",
    image: pm,
  },
  {
    title: "Data Science",
    description:
      "Analyze data, build models & make predictions with Python & ML.",
    rating: 4.8,
    students: "5.2K",
    link: "/data-science-roadmap",
    image: ds,
  },
  {
    title: "Artificial Intelligence",
    description:
      "Learn AI, Deep Learning, and Neural Networks to build smart systems.",
    rating: 4.9,
    students: "6.1K",
    link: "/ai-roadmap",
    image: ai,
  },
];

export default function CourseList() {
  return (
    <section className="bg-purple-50 py-12">
      <div className="max-w-6xl mx-auto px-6">
        <h2 className="text-3xl md:text-4xl font-bold text-center text-purple-900 mb-10">
          Our Popular Courses
        </h2>
        <div className="grid gap-8 md:grid-cols-3">
          {courses.map((course, idx) => (
            <div
              key={idx}
              className="bg-white rounded-2xl shadow-lg hover:shadow-xl transition p-6 flex flex-col items-center text-center"
            >
              {/* image */}
              <img
                src={course.image}
                alt={course.title}
                className="w-full h-48 object-contain rounded-xl mb-4"
              />

              <h3 className="text-xl font-semibold text-purple-900 mb-2">
                {course.title}
              </h3>
              <p className="text-gray-600 mb-4">{course.description}</p>
              <div className="text-gray-700 font-medium">
                {course.rating} ({course.students} ratings)
              </div>
              <Link
                to={course.link}
                className="mt-4 px-5 py-2 rounded-full bg-purple-600 text-white font-medium hover:bg-purple-700 transition"
              >
                Get Started
              </Link>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
