
import React from "react";
import "./App.css";
import { BrowserRouter, Routes, Route, useLocation } from "react-router-dom";

import Bar from "./Components/Bar";
import HeroSection from "./Components/HeroSection";
import About from "./Components/About";
import Learning from "./Components/Learning";
import Discount from "./Components/Discount";
import Faqs from "./Components/Faqs";
import Contact from "./Components/Contact";
import Footer from "./Components/Footer";
import AdminPanel from "./Components/AdminPanel";
import MyCourses from "./Components/MyCourses";
import MyDiscounts from "./Components/MyDiscounts";
import Success from "./Components/Success";
import Dashboard from "./Components/Dashboard";
import Courses from "./Components/Courselist";


import Login from "./Components/Login";
import Signup from "./Components/Signup";

import Stack from "./Components/Stack";
import Project from "./Components/Project";
import Digital from "./Components/Digital";
import Data from "./Components/Data";
import AI from "./Components/AI";
import PaymentPage from "./Components/PaymentPage";

import Enrollform from "./Components/EnrollForm";
import FullStackRoadmap from "./Components/FullStackRoadmap";
import DigitalMarketingRoadmap from "./Components/DigitalMarketingRoadmap";
import ProjectManagementRoadmap from "./Components/ProjectManagementRoadmap";
import DataScienceRoadmap from "./Components/DataScienceRoadmap";
import AIRoadmap from "./Components/AIRoadmap"; // roadmap file

// Home page content
const Home = () => {
  return (
    <>
      <HeroSection />
      <About />
      <Learning />
      <Discount />
      <Faqs />
      <Contact />
      <Footer />
    </>
  );
};

const MainApp = () => {
  const location = useLocation();

  // Hide Navbar only on login/signup
// Hide Navbar on login, signup, admin panel, and user dashboard
const hideNavbar = ["/login", "/signup", "/admin", "/dashboard"].includes(location.pathname);


  return (
    <>
      {!hideNavbar && <Bar />}

      <Routes>
        {/* Home page */}
        <Route path="/" element={<Home />} />

        {/* Standalone pages */}
        <Route path="/about" element={<About />} />
        <Route path="/EnrollForm" element={<Enrollform />} />
        <Route path="/pricing" element={<Discount />} />
        <Route path="/contact" element={<Contact />} />
        <Route path="/success" element={<Success />} />
        <Route path="/courses" element={<Courses />} />
        <Route path="/dashboard" element={<Dashboard />} />

        <Route path="/payment" element={<PaymentPage />} />
        
<Route path="/admin" element={<AdminPanel />} />
<Route path="/my-courses" element={<MyCourses />} />
<Route path="/my-discounts" element={<MyDiscounts />} />

        {/* Auth pages */}
        <Route path="/login" element={<Login />} />
        <Route path="/signup" element={<Signup />} />

        {/* Other pages */}
        <Route path="/stack" element={<Stack />} />
        <Route path="/project" element={<Project />} />
        <Route path="/digital" element={<Digital />} />
        <Route path="/data" element={<Data />} />
        <Route path="/ai" element={<AI />} />

        {/* Roadmaps */}
        <Route path="/fullstack-roadmap" element={<FullStackRoadmap />} />
        <Route path="/digital-marketing-roadmap" element={<DigitalMarketingRoadmap />} />
        <Route path="/project-management-roadmap" element={<ProjectManagementRoadmap />} />
        <Route path="/data-science-roadmap" element={<DataScienceRoadmap />} />
        <Route path="/ai-roadmap" element={<AIRoadmap />} />
      </Routes>
    </>
  );
};

const AppWrapper = () => (
  <BrowserRouter>
    <MainApp />
  </BrowserRouter>
);

export default AppWrapper;
