// export default Bar;

import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import logo from "../Assets/LOGO.png";

const Bar = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  const toggleMenu = () => setIsOpen(!isOpen);

  useEffect(() => {
    const savedUser = JSON.parse(localStorage.getItem("user"));
    if (savedUser) {
      setUser(savedUser);
    }
  }, []);

  // ✅ Logout function
  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    setUser(null);
    navigate("/"); // ✅ redirect to Home instead of Login
  };

  return (
    <div className="bg-gradient-to-t from-purple-100 to-purple-200 h-auto w-full bg-no-repeat bg-cover pt-6 pb-8">
      <nav className="bg-white lg:mx-20 rounded-2xl">
        <div className="mx-auto max-w-7xl px-2 sm:px-6 lg:px-8">
          <div className="relative flex h-16 items-center justify-between">
            {/* Mobile menu button */}
            <div className="absolute inset-y-0 left-0 flex items-center sm:hidden">
              <button
                onClick={toggleMenu}
                type="button"
                className="inline-flex items-center justify-center rounded-md p-2 text-gray-400 hover:bg-purple-500 hover:text-white focus:outline-none focus:ring-2 focus:ring-inset focus:ring-white"
                aria-controls="mobile-menu"
                aria-expanded={isOpen}
              >
                <span className="sr-only">Open main menu</span>
                {isOpen ? (
                  <svg
                    className="block size-6"
                    fill="none"
                    viewBox="0 0 24 24"
                    strokeWidth="1.5"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      d="M6 18L18 6M6 6l12 12"
                    />
                  </svg>
                ) : (
                  <svg
                    className="block size-6"
                    fill="none"
                    viewBox="0 0 24 24"
                    strokeWidth="1.5"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5"
                    />
                  </svg>
                )}
              </button>
            </div>

            {/* Logo & Links */}
            <div className="flex flex-1 items-center justify-center sm:items-stretch sm:justify-start">
              <div className="flex shrink-0 items-center">
                <img className="h-8 w-auto" src={logo} alt="SkillShoot Logo" />
                <h4 className="text-purple-500 text-lg font-bold ml-2">
                  SkillShoot
                </h4>
              </div>

              {/* Desktop Menu */}
              <div className="hidden sm:flex flex-wrap items-center gap-3 md:pl-24 lg:pl-6">
                <div className="flex space-x-3 lg:gap-4 items-center">
                  <Link
                    to="/"
                    className="rounded-md lg:px-3 md:px-1 py-2 text-sm font-medium hover:text-purple-500"
                  >
                    Home
                  </Link>
                  <Link
                    to="/about"
                    className="rounded-md lg:px-3 md:px-1 py-2 text-sm font-medium hover:text-purple-500 whitespace-nowrap"
                  >
                    About us
                  </Link>
                  <Link
                    to="/courses"
                    className="rounded-md lg:px-3 md:px-1 py-2 text-sm font-medium hover:text-purple-500"
                  >
                    Courses
                  </Link>
                  <Link
                    to="/pricing"
                    className="rounded-md lg:px-3 md:px-1 py-2 text-sm font-medium hover:text-purple-500"
                  >
                    Pricing
                  </Link>
                  <Link
                    to="/contact"
                    className="rounded-md lg:px-3 md:px-1 py-2 text-sm font-medium hover:text-purple-500 whitespace-nowrap"
                  >
                    Contact us
                  </Link>

                  {/* ✅ Dashboard as text link */}
                  {user && (
                    <Link
                      to="/dashboard"
                      className="rounded-md lg:px-3 md:px-1 py-2 text-sm font-medium hover:text-purple-500"
                    >
                      My Profile
                    </Link>
                  )}

                  {/* ✅ Auth Buttons */}
                  {user ? (
                    <button
                      onClick={handleLogout}
                      className="px-4 py-1 h-10 bg-purple-300 text-black rounded-xl text-sm hover:bg-purple-400 whitespace-nowrap"
                    >
                      Logout
                    </button>
                  ) : (
                    <>
                      <Link to="/login">
                        <button className="ml-4 px-4 h-10 py-1 border border-purple-500 rounded-2xl text-purple-500 hover:bg-purple-500 hover:text-white text-sm whitespace-nowrap">
                          Login
                        </button>
                      </Link>
                      <Link to="/signup">
                        <button className="px-4 py-1 h-10 bg-purple-500 text-white rounded-xl text-sm hover:bg-purple-600 whitespace-nowrap">
                          Sign Up
                        </button>
                      </Link>
                    </>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Mobile Menu */}
        {isOpen && (
          <div className="sm:hidden" id="mobile-menu">
            <div className="space-y-1 px-2 pt-2 pb-3">
              <Link
                to="/"
                className="block rounded-md bg-purple-500 px-3 py-2 text-base font-medium text-white"
              >
                Home
              </Link>
              <Link
                to="/about"
                className="block rounded-md px-3 py-2 text-base font-medium text-gray-300 hover:bg-purple-500 hover:text-white"
              >
                About us
              </Link>
              <Link
                to="/courses"
                className="block rounded-md px-3 py-2 text-base font-medium text-gray-300 hover:bg-purple-500 hover:text-white"
              >
                Courses
              </Link>
              <Link
                to="/pricing"
                className="block rounded-md px-3 py-2 text-base font-medium text-gray-300 hover:bg-purple-500 hover:text-white"
              >
                Pricing
              </Link>
              <Link
                to="/contact"
                className="block rounded-md px-3 py-2 text-base font-medium text-gray-300 hover:bg-purple-500 hover:text-white"
              >
                Contact us
              </Link>

              {/* ✅ Dashboard for Mobile */}
              {user && (
                <Link
                  to="/dashboard"
                  className="block rounded-md px-3 py-2 text-base font-medium text-gray-300 hover:bg-purple-500 hover:text-white"
                >
                  My Profile
                </Link>
              )}

              {user ? (
                <button
                  onClick={handleLogout}
                  className="w-full mt-2 px-4 py-2 bg-purple-300 text-black rounded-xl text-base hover:bg-purple-400"
                >
                  Logout
                </button>
              ) : (
                <>
                  <Link to="/login">
                    <button className="w-full mt-2 px-4 py-2 border border-purple-500 rounded-xl text-purple-500 hover:bg-purple-500 hover:text-white text-base">
                      Login
                    </button>
                  </Link>
                  <Link to="/signup">
                    <button className="w-full mt-2 px-4 py-2 bg-purple-500 text-white rounded-xl text-base hover:bg-purple-600">
                      Sign Up
                    </button>
                  </Link>
                </>
              )}
            </div>
          </div>
        )}
      </nav>
    </div>
  );
};

export default Bar;
