import React, { useEffect, useState } from "react";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
  BarChart,
  Bar,
} from "recharts";
import { CreditCard } from "lucide-react"; // icon
import { useNavigate } from "react-router-dom"; // add this

const Dashboard = () => {
  const navigate = useNavigate(); // initialize navigate
  const [user, setUser] = useState(null);
  const [enrollments, setEnrollments] = useState([]);
  const [payments, setPayments] = useState([]);

  useEffect(() => {
    const u = JSON.parse(localStorage.getItem("user"));
    if (u) {
      setUser(u);
      const email = u.email.trim().toLowerCase();

      // fetch enrollments of user
      fetch(`http://localhost:5000/api/my-enrollments/${email}`)
        .then((res) => res.json())
        .then((data) => {
          if (data.success) setEnrollments(data.forms);
          else console.error("Enrollments fetch failed:", data.message);
        })
        .catch((err) => console.error("Error fetching enrollments:", err));

      // fetch payments of user
      fetch(`http://localhost:5000/api/my-payments/${email}`)
        .then((res) => res.json())
        .then((data) => {
          if (data.success) setPayments(data.payments);
          else console.error("Payments fetch failed:", data.message);
        })
        .catch((err) => console.error("Error fetching payments:", err));
    }
  }, []);

  if (!user) return <div className="p-6">Loading...</div>;

  // Area graph data
  const graphData = enrollments.map((e) => ({
    date: new Date(e.date).toLocaleDateString(),
    amount: e.amount || 0,
  }));

  // Bar graph data: group enrollments by course
  const courseCount = {};
  enrollments.forEach((e) => {
    courseCount[e.course] = (courseCount[e.course] || 0) + 1;
  });
  const barData = Object.keys(courseCount).map((c) => ({
    course: c,
    count: courseCount[c],
  }));

  return (
    <div className="max-w-6xl mx-auto p-6">
      {/* Back to Home Button */}
      <div className="mb-6">
        <button
          onClick={() => navigate("/")}
          className="bg-purple-600 text-white px-4 py-2 rounded-lg hover:bg-purple-700 transition"
        >
          ← Back to Home
        </button>
      </div>

      <h1 className="text-3xl font-bold mb-4">
        Welcome{" "}
        <span className="text-purple-600">
          {user.firstName} {user.lastName}
        </span>
      </h1>

      <div className="bg-white shadow-md rounded-xl p-6 mb-6">
        <p className="text-gray-700">
          <strong>📞 Phone:</strong> {user.phone}
        </p>
        <p className="text-gray-700">
          <strong>📧 Email:</strong> {user.email}
        </p>
      </div>

      <div className="grid md:grid-cols-2 gap-6 mb-6">
        <div className="bg-white shadow-md rounded-xl p-4">
          <h3 className="text-sm font-semibold mb-2">Enrollment Trend</h3>
          {graphData.length > 0 ? (
            <ResponsiveContainer width="100%" height={200}>
              <AreaChart data={graphData}>
                <defs>
                  <linearGradient id="colorAmt" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#7c3aed" stopOpacity={0.8} />
                    <stop offset="95%" stopColor="#7c3aed" stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="date" />
                <YAxis />
                <Tooltip />
                <Area
                  type="monotone"
                  dataKey="amount"
                  stroke="#7c3aed"
                  fillOpacity={1}
                  fill="url(#colorAmt)"
                />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <p className="text-gray-600">No enrollments found</p>
          )}
        </div>

        <div className="bg-white shadow-md rounded-xl p-4">
          <h3 className="text-sm font-semibold mb-2">Enrollments by Course</h3>
          {barData.length > 0 ? (
            <ResponsiveContainer width="100%" height={200}>
              <BarChart data={barData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="course" />
                <YAxis />
                <Tooltip />
                <Bar dataKey="count" fill="#9333EA" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          ) : (
            <p className="text-gray-600">No enrollments found</p>
          )}
        </div>
      </div>

      <h2 className="text-xl font-bold mt-6 mb-4">💳 Your Payments</h2>
      {payments.length === 0 ? (
        <p className="text-gray-600">No payments found</p>
      ) : (
        <div className="grid md:grid-cols-2 gap-6">
          {payments.map((p) => (
            <div
              key={p._id}
              className="bg-gradient-to-r from-purple-50 to-purple-100 shadow-lg rounded-2xl p-6 hover:shadow-xl transition"
            >
              <div className="flex items-center mb-4">
                <CreditCard className="text-purple-600 mr-2" />
                <h3 className="text-lg font-semibold text-purple-700">{p.course}</h3>
              </div>
              <div className="space-y-1 text-gray-700">
                <p>
                  <strong>Amount:</strong> ${p.amount}
                </p>
                <p>
                  <strong>Method:</strong>{" "}
                  <span className="capitalize">{p.paymentMethod}</span>
                </p>
                <p>
                  <strong>Status:</strong>{" "}
                  <span
                    className={
                      p.status === "success"
                        ? "text-green-600 font-medium"
                        : "text-yellow-600 font-medium"
                    }
                  >
                    {p.status}
                  </span>
                </p>
                <p>
                  <strong>Date:</strong> {new Date(p.createdAt).toLocaleString()}
                </p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Dashboard;
