


import React, { useEffect, useRef, useState } from 'react';
import web from "../Assets/fs3.png";
import pm from "../Assets/pm1.avif";
import dm from "../Assets/dm1.webp";
import ds from "../Assets/ds.jpg";
import ai from "../Assets/ai.jpeg";
import { Link } from 'react-router-dom';

const Learning = () => {
  const [visible, setVisible] = useState(false);
  const sectionRef = useRef();

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  return (
    <div ref={sectionRef} id='course'>
      <div className="h-auto pb-4 pt-6 w-full bg-gradient-to-t from-white to-purple-200">
        <h1
          className={`text-center font-bold text-5xl pb-6 transition-all duration-1000 ${
            visible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
          }`}
        >
          Interactive Learning Experience
        </h1>

        <div className="flex flex-col h-auto mt-4 gap-6 justify-center px-4">
          {/* Cards */}
          <div className="flex flex-row flex-wrap justify-center gap-10">
            {/* Full Stack */}
            <div
              className={`border-2 border-white h-100 w-[27%] min-w-[250px] flex flex-col items-start justify-center  p-2 gap-2 bg-white transition-all duration-1000 ease-out ${
                visible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
              }`}
              style={{ transitionDelay: '0ms' }}
            >
              <img src={web} alt="Full Stack" className='h-[280px]' />
              <Link to='/stack'>
                <h2 className="font-bold">Full Stack Web Developer</h2>
              </Link>
              <div className="flex gap-2 border-t-2 ">
                <div className="font-bold">★ 4.7</div>
                <div className="font-thin  ">447K rating</div>
              </div>
            </div>

            {/* Digital Marketing */}
            <div
              className={`border-2 border-white h-100 w-[27%] min-w-[250px] flex flex-col items-start justify-center p-2 gap-2 bg-white transition-all duration-1000 ease-out ${
                visible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
              }`}
              style={{ transitionDelay: '200ms' }}
            >
              <img src={dm} alt="Digital Marketing" className='h-[280px]' />
              <Link to='/digital'>
                <h2 className="font-bold">Digital Marketing</h2>
              </Link>
              <div className="flex gap-2 border-t-2 ">
                <div className=" font-bold">★ 4.7</div>
                <div className="font-thin">447K rating</div>
              </div>
            </div>

            {/* Project Management */}
            <div
              className={`border-2 border-white h-100 w-[27%] min-w-[250px] flex flex-col items-start justify-center p-2 gap-2 bg-white transition-all duration-1000 ease-out ${
                visible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
              }`}
              style={{ transitionDelay: '400ms' }}
            >
              <img src={pm} alt="Project Management" className='h-[280px]' />
              <Link to='/project'>
                <h2 className="font-bold">Project Management</h2>
              </Link>
              <div className="flex gap-2 border-t-2 ">
                <div className="font-bold">★ 4.7</div>
                <div className="font-thin">447K rating</div>
              </div>
            </div>
{/* data science */}
             <div
              className={`border-2 border-white h-100 w-[27%] min-w-[250px] flex flex-col items-start justify-center  p-2 gap-2 bg-white transition-all duration-1000 ease-out ${
                visible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
              }`}
              style={{ transitionDelay: '0ms' }}
            >
              <img src={ds} alt="Full Stack" className='h-[280px]' />
              <Link to='/data'>
                <h2 className="font-bold">Data Science</h2>
              </Link>
              <div className="flex gap-2 border-t-2 ">
                <div className="font-bold">★ 4.7</div>
                <div className="font-thin  ">447K rating</div>
              </div>
            </div>
{/* artificial intelligence */}
             <div
              className={`border-2 border-white h-100 w-[27%] min-w-[250px] flex flex-col items-start justify-center  p-2 gap-2 bg-white transition-all duration-1000 ease-out ${
                visible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
              }`}
              style={{ transitionDelay: '0ms' }}
            >
              <img src={ai} alt="Full Stack" className='h-[280px]' />
              <Link to='/ai'>
                <h2 className="font-bold">Artificial Intelligence</h2>
              </Link>
              <div className="flex gap-2 border-t-2 ">
                <div className="font-bold">★ 4.7</div>
                <div className="font-thin  ">447K rating</div>
              </div>
            </div>

            
          </div>
        </div>
      </div>
    </div>
  );
};

export default Learning;
