// src/Components/Data.js
import React from "react";
import { Link } from "react-router-dom";
import web from "../Assets/ds.jpg"; // <-- apni image ka sahi path dalna
// import logo from "../assets/logo.png"; // agar top bar use karna ho

const Data = () => {
  return (
    <div>
      {/* Main Section */}
      <div className="bg-gradient-to-t from-white to-purple-200 py-10 px-6">
        <div className="flex flex-col-reverse lg:flex-row justify-between items-center gap-10">
          
          {/* Left Text */}
          <div className="w-full lg:w-1/2 text-left pl-8">
            <h1 className="font-bold text-3xl sm:text-4xl md:text-5xl text-black">
              Data Science
            </h1>
            <p className="pt-6 text-black text-base sm:text-lg">
              Kickstart your journey into Data Science .<br />
              Learn Python, Machine Learning, and Deep Learning step by step.<br />
              Build projects and get job-ready skills.
            </p>

            {/* Stats */}
            <div className="flex flex-wrap gap-6 pt-6">
              <div className="flex flex-col text-black">
                <p className="font-bold text-lg">★ 4.8</p>
                <p className="text-sm">average course rating</p>
              </div>
              <div className="flex flex-col text-black">
                <p className="font-bold text-lg">142</p>
                <p className="text-sm">practice exercises</p>
              </div>
              <div className="flex flex-col text-black">
                <p className="font-bold text-lg">95.3</p>
                <p className="text-sm">hours of content</p>
              </div>
            </div>

            {/* Get Started button with roadmap link */}
            <Link
              to="/data-science-roadmap"
              className="border mt-6 justify-center p-4 w-[170px] bg-purple-500 text-white flex rounded-2xl hover:bg-purple-600 transition"
            >
              Get started <i className="fa-solid fa-arrow-right ml-2 mt-1"></i>
            </Link>
          </div>

          {/* Right Image */}
          <div className="w-full lg:w-1/2 flex justify-center">
            <img
              src={web}
              alt="Data Science"
              className="w-full max-w-[450px] h-auto rounded-lg"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default Data;
