// src/pages/MyCourses.jsx
import React, { useEffect, useState } from "react";

const MyCourses = ({ userId }) => {
  const [courses, setCourses] = useState([]);

  useEffect(() => {
    if (!userId) return; // jab tak userId na mile, request mat bhejo
    fetch(`http://localhost:5000/api/my-courses/${userId}`)
      .then((res) => res.json())
      .then((data) => setCourses(data.courses || []))
      .catch((err) => console.error(err));
  }, [userId]);

  return (
    <div className="p-10 bg-gray-100 min-h-screen">
      <h1 className="text-2xl font-bold text-purple-700 mb-6">My Courses</h1>
      {courses.length === 0 ? (
        <p>No courses enrolled yet.</p>
      ) : (
        <ul className="space-y-4">
          {courses.map((c, i) => (
            <li key={i} className="bg-white shadow-md rounded-lg p-4">
              <h2 className="font-bold">{c.courseId?.title || "N/A"}</h2>
              <p>Price Paid: ${c.pricePaid}</p>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default MyCourses;
