// src/Components/AI.js
import React from "react";
import { Link } from "react-router-dom";
import ai from "../Assets/ai.jpeg"; // <-- apni AI image ka path yahan dalna

const AI = () => {
  return (
    <div>
      {/* Main Section */}
      <div className="bg-gradient-to-t from-white to-purple-100 py-10 px-6">
        <div className="flex flex-col-reverse lg:flex-row justify-between items-center gap-10">
          
          {/* Left Text */}
          <div className="w-full lg:w-1/2 text-left pl-8">
            <h1 className="font-bold text-3xl sm:text-4xl md:text-5xl text-black">
              Artificial Intelligence
            </h1>
            <p className="pt-6 text-black text-base sm:text-lg">
              Start your journey in Artificial Intelligence.<br />
              Learn Machine Learning, Deep Learning, and AI tools.<br />
              Build real-world AI models and applications.
            </p>

            {/* Stats */}
            <div className="flex flex-wrap gap-6 pt-6">
              <div className="flex flex-col text-black">
                <p className="font-bold text-lg">★ 4.9</p>
                <p className="text-sm">average course rating</p>
              </div>
              <div className="flex flex-col text-black">
                <p className="font-bold text-lg">98</p>
                <p className="text-sm">practice exercises</p>
              </div>
              <div className="flex flex-col text-black">
                <p className="font-bold text-lg">105.4</p>
                <p className="text-sm">hours of content</p>
              </div>
            </div>

            {/* Get Started button with roadmap link */}
            <Link
              to="/ai-roadmap"
              className="border mt-6 justify-center p-4 w-[170px] bg-indigo-500 text-white flex rounded-2xl hover:bg-indigo-600 transition"
            >
              Get started <i className="fa-solid fa-arrow-right ml-2 mt-1"></i>
            </Link>
          </div>

          {/* Right Image */}
          <div className="w-full lg:w-1/2 flex justify-center">
            <img
              src={ai}
              alt="Artificial Intelligence"
              className="w-full max-w-[450px] h-auto rounded-lg"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default AI;
