// export default Signup;



import React, { useState } from "react";
import { ToastContainer, toast } from "react-toastify";
import 'react-toastify/dist/ReactToastify.css';
import logo from "../Assets/LOGO.png";
import log from "../Assets/log.webp";

const Signup = () => {
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const handleSignup = async () => {
    if (!firstName || !lastName || !phone || !email || !password) {
      return toast.error("Please enter all fields");
    }

    try {
      const res = await fetch("http://localhost:5000/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ firstName, lastName, phone, email, password }),
      });

      const data = await res.json();

      if (data.success) {
        // Save token & user in localStorage
        localStorage.setItem("token", data.token);
        localStorage.setItem("user", JSON.stringify(data.user));

        toast.success("Signup successful ✅");

        // Redirect to HOME after 2 seconds
        setTimeout(() => {
          window.location.href = "/";
        }, 2000);
      } else {
        toast.error(data.message || "Signup failed");
      }
    } catch (error) {
      console.error(error);
      toast.error("Server error");
    }
  };

  return (
    <div>
      <ToastContainer position="top-right" autoClose={3000} />
      {/* Navbar */}
      <div className="flex justify-center pt-2 pb-2 items-center shadow-md">
        <img className="h-8 w-auto" src={logo} alt="Your Company" />
        <h4 className="text-purple-500 text-3xl font-bold ml-2">SkillShoot</h4>
      </div>

      <div className="flex flex-row flex-wrap justify-evenly mt-10">
        <div className="w-80">
          <img src={log} alt="" />
        </div>

        <div className="flex flex-col">
          <div className="text-center font-bold text-3xl pt-8">
            <h1>Create your account</h1>
          </div>

          {/* First Name */}
          <div className="flex mt-8 px-2">
            <input
              type="text"
              placeholder="First Name"
              value={firstName}
              onChange={(e) => setFirstName(e.target.value)}
              className="h-[50px] border rounded-md border-black w-full font-bold placeholder:text-black pl-4"
            />
          </div>

          {/* Last Name */}
          <div className="flex mt-4 px-2">
            <input
              type="text"
              placeholder="Last Name"
              value={lastName}
              onChange={(e) => setLastName(e.target.value)}
              className="h-[50px] border rounded-md border-black w-full font-bold placeholder:text-black pl-4"
            />
          </div>

          {/* Phone Number */}
          <div className="flex mt-4 px-2">
            <input
              type="text"
              placeholder="Phone Number"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              className="h-[50px] border rounded-md border-black w-full font-bold placeholder:text-black pl-4"
            />
          </div>

          {/* Email */}
          <div className="flex mt-4 px-2">
            <input
              type="text"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="h-[50px] border rounded-md border-black w-full font-bold placeholder:text-black pl-4"
            />
          </div>

          {/* Password */}
          <div className="flex mt-4 px-2">
            <input
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="h-[50px] border rounded-md border-black w-full font-bold placeholder:text-black pl-4"
            />
          </div>

          {/* Signup Button */}
          <div
            onClick={handleSignup}
            className="cursor-pointer flex border h-[50px] bg-purple-500 flex-row items-center justify-center mt-8 w-[95%] mx-auto rounded-md gap-2"
          >
            <div className="text-white">
              <i className="fa-regular fa-envelope"></i>
            </div>
            <div className="font-bold text-white">Sign Up</div>
          </div>

          <div className="mb-4 mt-4 text-center">
            <p>
              Already have an account?{" "}
              <a href="/login" className="underline text-purple-600">
                Login
              </a>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Signup;
