// export default AdminPanel;


import React, { useEffect, useState } from "react";

const AdminPanel = () => {
  const [payments, setPayments] = useState([]);
  const [stats, setStats] = useState({ totalRevenue: 0, methodBreakdown: [] });

  useEffect(() => {
    // Payments
    fetch("http://localhost:5000/api/payments")
      .then((res) => res.json())
      .then((data) => setPayments(data.payments || []));

    // Stats
    fetch("http://localhost:5000/api/payment-stats")
      .then((res) => res.json())
      .then((data) => setStats(data || { totalRevenue: 0, methodBreakdown: [] }));
  }, []);

  return (
    <div className="p-10 bg-gray-100 min-h-screen">
      <h1 className="text-4xl font-bold mb-10 text-purple-700">Admin Dashboard</h1>
      
      {/* Payments Table */}
      <div className="bg-white shadow-md rounded-lg p-6 mb-10">
        <h2 className="text-2xl font-semibold mb-4">User's Info</h2>
        <table className="w-full border">
          <thead>
            <tr className="bg-purple-100">
              <th className="border px-4 py-2">User</th>
              <th className="border px-4 py-2">Course</th>
              <th className="border px-4 py-2">Method</th>
              <th className="border px-4 py-2">Amount</th>
              <th className="border px-4 py-2">Status</th>
              <th className="border px-4 py-2">Date</th>
            </tr>
          </thead>
          <tbody>
            {payments.map((p, i) => (
              <tr key={i}>
                <td className="border px-4 py-2">{p.email}</td>
                <td className="border px-4 py-2">{p.course}</td>
                <td className="border px-4 py-2">{p.paymentMethod}</td>
                <td className="border px-4 py-2">${p.amount}</td>
                <td className="border px-4 py-2">{p.status}</td>
                <td className="border px-4 py-2">{new Date(p.createdAt).toLocaleDateString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-10">
        <div className="bg-white shadow-md rounded-xl p-6 text-center">
          <h2 className="text-lg font-semibold text-gray-600">Revenue</h2>
          <p className="text-3xl font-bold text-green-600">${stats.totalRevenue}</p>
        </div>

        <div className="bg-white shadow-md rounded-xl p-6 text-center">
          <h2 className="text-lg font-semibold text-gray-600">Payment Breakdown</h2>
          <ul className="mt-4 text-left">
            {stats.methodBreakdown.map((m, i) => (
              <li key={i}>
                <span className="font-semibold capitalize">{m._id}</span>: {m.total} payments
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
};

export default AdminPanel;







